    @Transient
    private Boolean capacityWarning;

    /**
     * The number of owners sharing this owner's household (the same householdId),
     * counting this owner. Derived at response time from the persisted householdId,
     * never persisted. Drives the 'GOLD' membership tier (3 or more members).
     */
    @Transient
    private Integer householdSize;

    /**
     * Whether this owner is a soft-match of an existing (other) owner — sharing that
     * owner's lastName and postcode but carrying a different telephone (so it is not a
     * hard duplicate). Derived at response time, never persisted.
     */
    @Transient
    private Boolean possibleDuplicate;

    /**
     * The id of the existing owner this owner soft-matches (see {@link #possibleDuplicate}),
     * or null when it soft-matches none. Derived at response time, never persisted.
     */
    @Transient
    private Integer possibleDuplicateOf;

    /**
     * The owner's membership level, capped so it never exceeds one above the current
     * maximum level among the other members of its household. Derived at response time
     * from the persisted fields plus the household, never persisted. When null (e.g. for
     * list responses that skip the assignment step) the level falls back to the uncapped
